plan = json.loads((ROOT/'audit/runs/next-shard-0005-plan.json').read_text(encoding='utf-8'))
assert set(D) == set(plan['questionIds']).intersection(bank)
for qid,(keys,reasons,challenge) in D.items():
    r = review_template(bank[qid])
    r['reviewer'] = 'Codex'
    r['manual'] = {k: True for k in r['manual']}
    r['notes'] = 'Read all four answers and relevant full topic digests/category context; checked cross-bank matches, wording, scope, category and editorial difficulty. ' + challenge
    sources = [{'url':S[k][0],'locator':S[k][1]} for k in keys]
    v = r['verification']
    v.update(context=bank[qid]['question'],timeSensitive=False,nextReviewAt=None)
    v['premise'] = {'reason':reasons[0],'sources':sources}
    v['challenge'] = {'reviewer':'Codex','at':r['at'],'premiseChecked':True,'alternativesExcluded':True,'notes':challenge}
    for i,opt in enumerate(v['options']):
        opt.update(reason=reasons[i],sources=sources,basis='direct' if i==0 else 'exclusive-inference')
    if qid in {212,215,217,223,225,231,233,240,241,245,246}:
        for opt in v['options'][1:]:
            opt['basis']='contradiction'
    (OUT/f'{qid}.json').write_text(json.dumps(r,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print(f'Saved {len(D)} final-wording reviews.')
